# Stonebreak test-system registry — single source of truth for `run-tests.sh`.
#
# Format (tab-separated):  system<TAB>module<TAB>pattern[,pattern...]
#   - Patterns are paths relative to <module>/src/test/java, without the .java
#     extension. `**` crosses directories, `*` stays within one segment.
#   - A `!` prefix excludes; excludes are scoped to THIS line only.
#   - A system may span modules (one line per module).
# Every *Test.java in every module must map to exactly ONE system —
# harness.py validates this on every run and aborts on drift.

# ---- engine ----
cenda	stonebreak-game	com/stonebreak/world/chunk/api/mightyMesh/mmsIntegration/CendaMesherKernelTest,com/stonebreak/world/CendaChunkBenchmarkTest
networking	stonebreak-game	com/stonebreak/network/**/*Test
mms	stonebreak-game	com/stonebreak/world/chunk/api/mightyMesh/**/*Test,!com/stonebreak/world/chunk/api/mightyMesh/mmsIntegration/CendaMesherKernelTest
lighting	stonebreak-game	com/stonebreak/rendering/lighting/**/*Test,com/stonebreak/world/lighting/**/*Test
cearl	stonebreak-game	com/stonebreak/rendering/vram/**/*Test
shaders	stonebreak-game	com/stonebreak/rendering/core/**/*Test

# ---- game ----
audio	stonebreak-game	com/stonebreak/audio/**/*Test
blocks	stonebreak-game	com/stonebreak/blocks/**/*Test,!com/stonebreak/blocks/waterSystem/**,com/stonebreak/util/**/*Test
water	stonebreak-game	com/stonebreak/blocks/waterSystem/**/*Test,com/stonebreak/world/chunk/ChunkWaterLayerTest,com/stonebreak/world/chunk/WaterMeshSplitTest,com/stonebreak/world/chunk/WaterSurfaceClosureTest
core	stonebreak-game	com/stonebreak/core/**/*Test,com/stonebreak/config/**/*Test,com/stonebreak/world/TimeOfDayTest,com/stonebreak/world/DeterministicRandomTest,com/stonebreak/world/SnowLayerManagerTest
items	stonebreak-game	com/stonebreak/items/**/*Test,com/stonebreak/gameplay/**/*Test
weather	stonebreak-game	com/stonebreak/world/weather/**/*Test,com/stonebreak/world/MoonCycleTest
input	stonebreak-game	com/stonebreak/input/**/*Test
crafting	stonebreak-game	com/stonebreak/crafting/**/*Test
mobs	stonebreak-game	com/stonebreak/mobs/**/*Test,com/stonebreak/rendering/models/**/*Test,com/stonebreak/vehicles/**/*Test
player	stonebreak-game	com/stonebreak/player/**/*Test,com/stonebreak/rpg/**/*Test,com/stonebreak/rendering/player/**/*Test,com/stonebreak/battletest/**/*Test
battle	stonebreak-game	com/stonebreak/battle/**/*Test
ui	stonebreak-game	com/stonebreak/ui/**/*Test,com/stonebreak/rendering/UI/**/*Test
chunks	stonebreak-game	com/stonebreak/world/chunk/**/*Test,!com/stonebreak/world/chunk/api/**,!com/stonebreak/world/chunk/ChunkWaterLayerTest,!com/stonebreak/world/chunk/WaterMeshSplitTest,!com/stonebreak/world/chunk/WaterSurfaceClosureTest,com/stonebreak/world/LoadingPerformanceIntegrationTest
fastlod	stonebreak-game	com/stonebreak/world/fastlod/**/*Test,com/stonebreak/rendering/gameWorld/**/*Test
leaves	stonebreak-game	com/stonebreak/world/leaves/**/*Test,com/stonebreak/world/growth/**/*Test
terrain-gen	stonebreak-game	com/stonebreak/world/generation/**/*Test,com/stonebreak/world/spawn/**/*Test
persistence	stonebreak-game	com/stonebreak/world/save/**/*Test
bench	stonebreak-game	com/stonebreak/world/bench/**/*Test

# ---- tool ----
plugins	openmason-plugin-stonebreak	com/stonebreak/openmason/**/*Test
